-- Alabama had five stops.
--
-- World's Smallest City Block dropped: already here, two metres away, under a
-- straight apostrophe rather than a curly one.
--
-- Tennessee, Alabama and Mississippi are Central time; so are Illinois,
-- Wisconsin and Louisiana. No county exceptions in any of the six.
--
-- 119 stops.

insert into public.stops
  (name, slug, category, latitude, longitude, city, state, description,
   public_access, source, website, timezone, verified_at)
values
  ('Dead Children’s Playground — Maple Hill Cemetery', 'dead-childrens-playground-maple-hill-cemetery', 'haunted', 34.73148, -86.56519, 'Huntsville', 'AL', 'Behind Maple Hill Cemetery, a small playground has become one of Huntsville’s best-known ghost-story locations, with local tales of children’s apparitions and swings moving on their own. The supernatural claims are folklore, not established fact; visit only during lawful cemetery/park hours and remain respectful of graves and mourners.', 'limited', 'https://alabama.travel/article/the-most-haunted-places-in-alabama', null, 'America/Chicago', now()),
  ('U.S. Space & Rocket Center', 'us-space-rocket-center', 'weird-history', 34.71139, -86.65417, 'Huntsville', 'AL', 'One of the largest spaceflight museums in the country preserves rockets, spacecraft, engines and artifacts connected to Huntsville’s role in the American space program. Its full-scale Saturn V and dense collection of hardware make it one of Alabama’s strongest science-history OddWay stops.', 'open', 'https://www.rocketcenter.com/', null, 'America/Chicago', now()),
  ('Alabama Constitution Hall Park', 'alabama-constitution-hall-park', 'weird-history', 34.72862, -86.58737, 'Huntsville', 'AL', 'This reconstructed village interprets Huntsville in 1819, when delegates gathered here to draft Alabama’s first state constitution. Demonstrations and restored-style buildings turn a pivotal political moment into a physical historic district rather than a simple marker.', 'limited', 'https://earlyworks.com/achp/', null, 'America/Chicago', now()),
  ('Burritt on the Mountain', 'burritt-on-the-mountain', 'weird-history', 34.71583, -86.53944, 'Huntsville', 'AL', 'Dr. William Burritt’s unusual 1930s mountaintop mansion combines eclectic architecture with a recreated nineteenth-century farm village. The elevated site, old cabins and distinctive mansion give it more OddWay character than a conventional house museum.', 'open', 'https://burrittonthemountain.com/', null, 'America/Chicago', now()),
  ('Weeden House Museum and Garden', 'weeden-house-museum-and-garden', 'weird-history', 34.72896, -86.58369, 'Huntsville', 'AL', 'This early nineteenth-century home survived Huntsville’s transformation and later became associated with artist and poet Maria Howard Weeden. Guided access preserves both the architecture and the complicated history of the people who lived and worked there.', 'limited', 'https://weedenhousemuseum.com/', null, 'America/Chicago', now()),
  ('Harrison Brothers Hardware', 'harrison-brothers-hardware', 'museums', 34.72981, -86.58433, 'Huntsville', 'AL', 'Operating in a downtown storefront dating to the nineteenth century, Harrison Brothers preserves old counters, fixtures and merchandise displays while still functioning as a shop. It feels like a hardware store frozen between museum and working business.', 'open', 'https://harrisonbrothershardware.com/', null, 'America/Chicago', now()),
  ('North Alabama Railroad Museum', 'north-alabama-railroad-museum', 'weird-history', 34.78347, -86.54588, 'Huntsville', 'AL', 'The museum preserves locomotives, passenger cars, freight equipment and the historic Chase Depot, with excursion trains offered on selected dates. The combination of rolling stock and a functioning heritage railroad makes it a strong industrial-history stop.', 'limited', 'https://narm.info/', null, 'America/Chicago', now()),
  ('U.S. Veterans Memorial Museum', 'us-veterans-memorial-museum', 'weird-history', 34.69063, -86.5858, 'Huntsville', 'AL', 'This volunteer-run museum displays military vehicles, uniforms, weapons and artifacts spanning conflicts from the Revolutionary era through the modern military. Its collection includes rare early military vehicles and unusual equipment not normally seen in general history museums.', 'limited', 'https://www.memorialmuseum.org/', null, 'America/Chicago', now()),
  ('Huntsville Depot Museum', 'huntsville-depot-museum', 'weird-history', 34.73454, -86.58991, 'Huntsville', 'AL', 'The surviving Huntsville Depot was once a major Memphis & Charleston Railroad stop and was used during the Civil War. Preserved rail-era spaces and exhibits document how the building moved soldiers, civilians and freight through north Alabama.', 'limited', 'https://earlyworks.com/huntsville-depot/', null, 'America/Chicago', now()),
  ('Lowe Mill ARTS & Entertainment', 'lowe-mill-arts-entertainment', 'roadside-oddities', 34.71515, -86.59704, 'Huntsville', 'AL', 'A sprawling former textile mill has been converted into a maze of artist studios, galleries, performance rooms and maker spaces. The building’s industrial shell and dense creative reuse make it feel closer to an inhabited art labyrinth than a conventional gallery complex.', 'open', 'https://lowemill.art/', null, 'America/Chicago', now()),
  ('Cook Museum of Natural Science', 'cook-museum-of-natural-science', 'museums', 34.60511, -86.98339, 'Decatur', 'AL', 'The Cook family’s collections grew from an interest in insects and pest-control education into a full natural-science museum. Today the exhibits range from preserved specimens and fossils to live animals and immersive ecosystems.', 'open', 'https://www.cookmuseum.org/', null, 'America/Chicago', now()),
  ('Old State Bank', 'old-state-bank', 'weird-history', 34.61432, -86.98365, 'Decatur', 'AL', 'This Greek Revival bank building opened in the 1830s and survived the Civil War destruction that erased much of Decatur. Its survival makes it a rare physical remnant of the city that existed before wartime rebuilding.', 'limited', 'https://www.decatur-al.gov/explore/things_to_do/museums_and_tours/old_state_bank.php', null, 'America/Chicago', now()),
  ('Alabama Veterans Museum & Archives', 'alabama-veterans-museum-archives', 'weird-history', 34.80675, -86.9702, 'Athens', 'AL', 'Housed in a former railroad freight depot, the museum preserves uniforms, documents, vehicles and personal stories from Alabama veterans. Its collection connects local lives to conflicts from the Revolutionary War through the present.', 'open', 'https://www.alabamaveteransmuseum.com/', null, 'America/Chicago', now()),
  ('Cathedral Caverns State Park', 'cathedral-caverns-state-park', 'roadside-oddities', 34.5737, -86.2216, 'Woodville', 'AL', 'The enormous entrance to Cathedral Caverns opens into a commercial cave filled with stalagmites, flowstone and immense chambers. Guided tours are required for cave access, while the surrounding state park offers surface recreation.', 'limited', 'https://www.alapark.com/parks/cathedral-caverns-state-park', null, 'America/Chicago', now()),
  ('Stephens Gap Callahan Cave Preserve', 'stephens-gap-callahan-cave-preserve', 'roadside-oddities', 34.67688, -86.22833, 'Woodville', 'AL', 'Stephens Gap is famous for a dramatic open pit and natural bridge that can be seen from the permitted approach, while technical cave routes require proper equipment and experience. Southeastern Cave Conservancy permits are mandatory; use SCCi’s directions rather than navigating cross-country to the coordinate.', 'limited', 'https://saveyourcaves.org/visit.html', null, 'America/Chicago', now()),
  ('Neversink Cave Preserve', 'neversink-cave-preserve', 'roadside-oddities', 34.8041, -86.007, 'Fackler', 'AL', 'Neversink is a spectacular open-air pit cave known for waterfalls, moss-covered walls and a deep vertical drop. It is a protected SCCi preserve requiring a permit, and entering the pit is technical vertical caving—not a casual hike.', 'limited', 'https://saveyourcaves.org/visit.html', null, 'America/Chicago', now()),
  ('Russell Cave National Monument', 'russell-cave-national-monument', 'weird-history', 34.9786, -85.80977, 'Bridgeport', 'AL', 'Russell Cave contains one of the Southeast’s most important archaeological records of repeated human occupation stretching back thousands of years. Visitors can follow the boardwalk to the massive shelter entrance, but entering the cave itself is prohibited.', 'open', 'https://www.nps.gov/ruca/index.htm', null, 'America/Chicago', now()),
  ('Sauta Cave National Wildlife Refuge', 'sauta-cave-national-wildlife-refuge', 'roadside-oddities', 34.61314, -86.13192, 'Scottsboro', 'AL', 'Sauta Cave protects major bat colonies, including large summer emergence flights. The cave entrances themselves are closed to public entry, but designated refuge areas allow lawful observation of the landscape and seasonal bat activity.', 'limited', 'https://www.recreation.gov/gateways/3925', null, 'America/Chicago', now()),
  ('Rock Zoo', 'rock-zoo', 'roadside-oddities', 34.79217, -86.03698, 'Fackler', 'AL', 'A roadside menagerie of painted boulders has been transformed into bulls, turtles, roosters and other animals. The folk-art display began with a single painted rock and grew into one of north Alabama’s strangest free roadside collections.', 'roadside', 'https://alabamarockzoo.com/', null, 'America/Chicago', now()),
  ('Unclaimed Baggage Museum', 'unclaimed-baggage-museum', 'museums', 34.67318, -86.04459, 'Scottsboro', 'AL', 'Inside the famous retailer that sells items from lost airline luggage is a museum of particularly bizarre, valuable or memorable objects recovered from suitcases over the years. The exhibit turns the mystery of lost baggage into a compact cabinet of curiosities.', 'open', 'https://www.unclaimedbaggage.com/', null, 'America/Chicago', now()),
  ('Scottsboro Boys Museum & Cultural Center', 'scottsboro-boys-museum-cultural-center', 'weird-history', 34.67395, -86.04134, 'Scottsboro', 'AL', 'Located in the former Joyce Chapel, the museum documents the Scottsboro Boys cases, in which nine Black teenagers were falsely accused of rape in 1931. Exhibits focus on the trials, appeals and their lasting significance in American civil-rights and legal history.', 'limited', 'https://www.thescottsboroboysmuseum.com/', null, 'America/Chicago', now()),
  ('Stevenson Railroad Depot Museum', 'stevenson-railroad-depot-museum', 'weird-history', 34.86763, -85.83977, 'Stevenson', 'AL', 'This nineteenth-century depot preserves the story of Stevenson’s position at a major railroad junction used heavily during the Civil War. Artifacts, local history and the depot itself make the surviving structure the centerpiece.', 'limited', 'https://encyclopediaofalabama.org/article/stevenson-railroad-depot-museum/', null, 'America/Chicago', now()),
  ('Fort Payne Depot Museum', 'fort-payne-depot-museum', 'weird-history', 34.44429, -85.71846, 'Fort Payne', 'AL', 'The sandstone depot built for the Alabama Great Southern Railroad now houses local artifacts and railroad history. Its heavy stone architecture and preserved rail setting make it one of Fort Payne’s most distinctive historic structures.', 'limited', 'https://fortpayne.org/community/museums/', null, 'America/Chicago', now()),
  ('Alabama Fan Club and Museum', 'alabama-fan-club-and-museum', 'weird-history', 34.43287, -85.73188, 'Fort Payne', 'AL', 'The hometown museum devoted to the country group Alabama displays awards, stage clothing, instruments and memorabilia spanning the band’s career. It is a concentrated piece of regional music history tied directly to Fort Payne.', 'open', 'https://fortpayne.org/community/museums/', null, 'America/Chicago', now()),
  ('Fort Payne Hosiery Museum', 'fort-payne-hosiery-museum', 'weird-history', 34.44588, -85.71984, 'Fort Payne', 'AL', 'Fort Payne once promoted itself as the Sock Capital of the World, and this small museum preserves machinery, products and stories from the city’s hosiery industry. Tours operate on a limited schedule, so visitors should check current hours before routing there.', 'limited', 'https://fortpayne.org/community/museums/', null, 'America/Chicago', now()),
  ('Little River Canyon National Preserve', 'little-river-canyon-national-preserve', 'roadside-oddities', 34.39866, -85.63382, 'Fort Payne', 'AL', 'Little River cuts a deep canyon across Lookout Mountain, creating waterfalls, cliffs and dramatic overlooks unusual for Alabama. Route visitors to the Canyon Center or established overlooks and trails rather than unmarked cliff edges.', 'open', 'https://www.nps.gov/liri/index.htm', null, 'America/Chicago', now()),
  ('Civilian Conservation Corps Museum — DeSoto State Park', 'civilian-conservation-corps-museum-desoto-state-park', 'weird-history', 34.50056, -85.61833, 'Fort Payne', 'AL', 'A small seasonal museum preserves photographs, tools and artifacts connected to the Civilian Conservation Corps crews that built major portions of DeSoto State Park during the 1930s. The park itself still contains their stonework and structures.', 'limited', 'https://www.alapark.com/parks/desoto-state-park/civilian-conservation-corps-museum', null, 'America/Chicago', now()),
  ('Sallie Howard Memorial Chapel', 'sallie-howard-memorial-chapel', 'roadside-oddities', 34.50556, -85.61556, 'Mentone', 'AL', 'Built in the 1930s as a memorial to Sallie Howard, this tiny chapel incorporates a huge natural boulder directly into its rear wall and altar area. It remains a functioning religious site, so visitors should respect services and private events.', 'limited', 'https://www.alapark.com/sites/default/files/2025-07/desoto%20sp_2024%20media%20Campground%20Map.pdf', null, 'America/Chicago', now()),
  ('Cherokee Rock Village', 'cherokee-rock-village', 'roadside-oddities', 34.18213, -85.81292, 'Leesburg', 'AL', 'Massive sandstone formations rise above Weiss Lake in a maze of cliffs, crevices and balancing-looking rocks. The landscape has long attracted climbers and hikers and also preserves evidence of Native American use.', 'open', 'https://www.cherokeerockvillage.com/', null, 'America/Chicago', now()),
  ('Ave Maria Grotto', 'ave-maria-grotto', 'roadside-oddities', 34.17535, -86.81646, 'Cullman', 'AL', 'Brother Joseph Zoettl spent decades building a miniature world of shrines, churches, temples and imaginary structures from stone, concrete, shells and discarded materials. More than a hundred miniature buildings fill the landscaped hillside at St. Bernard Abbey.', 'open', 'https://www.avemariagrotto.com/', null, 'America/Chicago', now()),
  ('Shrine of the Most Blessed Sacrament', 'shrine-of-the-most-blessed-sacrament', 'roadside-oddities', 34.05568, -86.68859, 'Hanceville', 'AL', 'This large Catholic shrine complex combines a Romanesque-Gothic church, cloisters and elaborate devotional architecture in rural Alabama. It remains an active religious site with visitor rules, dress expectations and service schedules.', 'limited', 'https://www.olamshrine.com/', null, 'America/Chicago', now()),
  ('Clarkson Covered Bridge', 'clarkson-covered-bridge', 'weird-history', 34.2072, -86.99017, 'Cullman', 'AL', 'A nineteenth-century covered bridge preserved in a county park crosses Crooked Creek beside a restored grist mill and pioneer buildings. The bridge has been moved and repaired over time but remains one of Alabama’s best-preserved covered-bridge landmarks.', 'open', 'https://www.cullmancountyparks.com/clarkson.html', null, 'America/Chicago', now()),
  ('Jesse Owens Memorial Park & Museum', 'jesse-owens-memorial-park-museum', 'weird-history', 34.43836, -87.16796, 'Oakville', 'AL', 'The park honors Olympic champion Jesse Owens near his birthplace with a museum, statue, track features and a replica of the sharecropper cabin where his family lived. It gives a physical route point to a globally significant Alabama-born athlete.', 'open', 'https://jesseowensmemorialpark.com/', null, 'America/Chicago', now()),
  ('Rickwood Caverns State Park', 'rickwood-caverns-state-park', 'roadside-oddities', 33.99648, -86.76014, 'Warrior', 'AL', 'Guided tours descend into a cave system filled with formations created over immense spans of geologic time. Surface trails and recreation are generally available more broadly, while cave access follows scheduled guided-tour operations.', 'limited', 'https://www.alapark.com/parks/rickwood-caverns-state-park', null, 'America/Chicago', now()),
  ('Natural Bridge of Alabama', 'natural-bridge-of-alabama', 'roadside-oddities', 34.09416, -87.61334, 'Natural Bridge', 'AL', 'A massive sandstone arch spans the forest and is promoted as the longest natural bridge east of the Rockies. The privately operated attraction uses established walking paths; visitors should check current operating hours before making a detour.', 'limited', 'https://alabama.travel/places-to-go/natural-bridge-of-alabama', null, 'America/Chicago', now()),
  ('Dismals Canyon', 'dismals-canyon', 'roadside-oddities', 34.32722, -87.7825, 'Phil Campbell', 'AL', 'This narrow sandstone gorge shelters colonies of bioluminescent larvae known locally as Dismalites, visible on certain guided night tours. Day hiking and night-tour schedules vary by season and weather, so advance checking is essential.', 'limited', 'https://www.dismalscanyon.com/', null, 'America/Chicago', now()),
  ('Wichahpi Commemorative Stone Wall', 'wichahpi-commemorative-stone-wall', 'roadside-oddities', 34.9473, -87.82267, 'Florence', 'AL', 'Tom Hendrix spent decades building a winding stone wall in memory of his Yuchi ancestor Te-lah-nay, who family tradition says returned to Alabama after forced removal. The hand-laid wall incorporates stones sent from around the world.', 'open', 'https://www.spacesarchives.org/explore/search-the-online-collection/tom-hendrix/', null, 'America/Chicago', now()),
  ('Key Underwood Coon Dog Memorial Graveyard', 'key-underwood-coon-dog-memorial-graveyard', 'weird-history', 34.63, -87.96667, 'Cherokee', 'AL', 'Established in 1937, this remote cemetery is reserved for coonhounds and contains headstones ranging from simple markers to elaborate memorials. It is a genuine cemetery for working dogs, not a novelty replica, so visitors should treat the grounds respectfully.', 'open', 'https://www.coondogcemetery.com/index.html', null, 'America/Chicago', now()),
  ('Rattlesnake Saloon', 'rattlesnake-saloon', 'roadside-oddities', 34.64816, -87.91091, 'Tuscumbia', 'AL', 'A restaurant and saloon sits beneath a huge natural rock overhang on the Seven Springs property, giving the dining area the appearance of a cave-front hideout. Operations are seasonal and days are limited, so check the current calendar before routing.', 'limited', 'https://www.rattlesnakesaloon.net/', null, 'America/Chicago', now()),
  ('Alabama Music Hall of Fame', 'alabama-music-hall-of-fame', 'weird-history', 34.71276, -87.70695, 'Tuscumbia', 'AL', 'Exhibits honor Alabama musicians across country, blues, gospel, soul and rock, with costumes, instruments, vehicles and recording memorabilia. The museum provides broad context for the state’s unusually dense music legacy.', 'open', 'https://www.alamhof.org/', null, 'America/Chicago', now()),
  ('Muscle Shoals Sound Studio — 3614 Jackson Highway', 'muscle-shoals-sound-studio-3614-jackson-highway', 'weird-history', 34.76778, -87.67389, 'Sheffield', 'AL', 'The small studio where the Muscle Shoals Rhythm Section recorded major artists remains preserved at its famous 3614 Jackson Highway address. Guided tours show the recording rooms and equipment tied to an outsized chapter of American music history.', 'limited', 'https://muscleshoalssoundstudio.org/', null, 'America/Chicago', now()),
  ('FAME Recording Studios', 'fame-recording-studios', 'weird-history', 34.74506, -87.66667, 'Muscle Shoals', 'AL', 'FAME became one of the defining recording studios of the Muscle Shoals sound, hosting artists across soul, rock and country. Scheduled tours allow visitors into the still-working studio rather than a reconstructed museum space.', 'limited', 'https://famestudios.com/', null, 'America/Chicago', now()),
  ('Ivy Green — Helen Keller Birthplace', 'ivy-green-helen-keller-birthplace', 'weird-history', 34.73795, -87.70582, 'Tuscumbia', 'AL', 'Helen Keller was born at this preserved family property in 1880, and the grounds include the cottage where she lived and the water pump associated with her breakthrough in learning language. The site preserves artifacts and family spaces connected to Keller and Anne Sullivan.', 'open', 'https://www.helenkellerbirthplace.org/', null, 'America/Chicago', now()),
  ('Frank Lloyd Wright Rosenbaum House', 'frank-lloyd-wright-rosenbaum-house', 'roadside-oddities', 34.79278, -87.68028, 'Florence', 'AL', 'Frank Lloyd Wright designed this Usonian house for the Rosenbaum family in 1939, integrating furniture, built-ins and low horizontal spaces into the plan. It is one of the few Wright houses in the Southeast open as a public museum.', 'limited', 'https://www.wrightinalabama.com/', null, 'America/Chicago', now()),
  ('Pope’s Tavern Museum', 'popes-tavern-museum', 'weird-history', 34.80498, -87.67693, 'Florence', 'AL', 'This early Florence tavern later served as a hospital during the Civil War and now contains local and wartime artifacts. Its layered use as inn, gathering place and medical site gives the small building an unusually dense history.', 'limited', 'https://www.florencealmuseums.com/home/popes-tavern', null, 'America/Chicago', now()),
  ('Florence Indian Mound Museum', 'florence-indian-mound-museum', 'weird-history', 34.7905, -87.67048, 'Florence', 'AL', 'A large prehistoric mound rises beside the museum, which interprets Native American cultures of the Tennessee Valley through artifacts and archaeology. The surviving earthwork gives visitors a direct physical connection to the region’s pre-European history.', 'limited', 'https://www.florencealmuseums.com/visit', null, 'America/Chicago', now()),
  ('Forks of Cypress Ruins', 'forks-of-cypress-ruins', 'weird-history', 34.845, -87.72556, 'Florence', 'AL', 'Only the massive brick columns and archaeological remains survive from the Forks of Cypress plantation house after a 1966 fire. The property is not a normal walk-in attraction; OddWay should treat it as a view-only historic ruin and never direct users through private barriers.', 'roadside', 'https://encyclopediaofalabama.org/article/forks-of-cypress/', null, 'America/Chicago', now()),
  ('Belle Mont Mansion', 'belle-mont-mansion', 'roadside-oddities', 34.66724, -87.66958, 'Tuscumbia', 'AL', 'This early nineteenth-century house is one of Alabama’s most important examples of Jeffersonian or Palladian-influenced architecture. The restored mansion is operated as a historic site with limited public hours and special events.', 'limited', 'https://ahc.alabama.gov/properties/bellemont/bellemont.aspx', null, 'America/Chicago', now()),
  ('Pond Spring — General Joe Wheeler Home', 'pond-spring-general-joe-wheeler-home', 'weird-history', 34.65062, -87.25388, 'Hillsboro', 'AL', 'The 50-acre historic site contains multiple houses, outbuildings, cemeteries, gardens and archaeological features associated with generations of Native, enslaved and later residents, as well as General Joseph Wheeler’s family. Tours operate on a limited schedule.', 'limited', 'https://ahc.alabama.gov/PondSpringHistoryFacts.aspx', null, 'America/Chicago', now()),
  ('LaGrange College Site Park', 'lagrange-college-site-park', 'weird-history', 34.6521, -87.5342, 'Leighton', 'AL', 'Alabama’s first chartered college once stood on this ridge before Union troops burned the campus during the Civil War. Today a historic park preserves the site with reconstructed buildings, markers and views over the Tennessee Valley.', 'open', 'https://www.lagrangehistoricsite.org/', null, 'America/Chicago', now()),
  ('Sloss Furnaces National Historic Landmark', 'sloss-furnaces-national-historic-landmark', 'weird-history', 33.52066, -86.79131, 'Birmingham', 'AL', 'Two blast furnaces, stoves, pipes and industrial structures survive from Birmingham’s ironmaking era, creating one of America’s most complete preserved furnace complexes. The raw machinery and towering infrastructure make Sloss one of the state’s defining OddWay industrial sites.', 'open', 'https://www.slossfurnaces.com/', null, 'America/Chicago', now()),
  ('Vulcan Park & Museum', 'vulcan-park-museum', 'roadside-oddities', 33.49171, -86.79601, 'Birmingham', 'AL', 'The colossal cast-iron statue of Vulcan was created for the 1904 World’s Fair and now overlooks Birmingham from Red Mountain. A museum and observation tower explain the giant figure and the iron industry that created it.', 'open', 'https://visitvulcan.com/', null, 'America/Chicago', now()),
  ('Barber Vintage Motorsports Museum', 'barber-vintage-motorsports-museum', 'museums', 33.53305, -86.61368, 'Birmingham', 'AL', 'Thousands of motorcycles and historic racing vehicles fill a multi-story museum beside Barber Motorsports Park. The sheer scale and density of machines make the collection visually unlike a normal automotive museum.', 'open', 'https://www.barbermuseum.org/', null, 'America/Chicago', now()),
  ('Southern Museum of Flight', 'southern-museum-of-flight', 'weird-history', 33.56349, -86.73806, 'Birmingham', 'AL', 'Aircraft, engines, military displays and experimental aviation artifacts fill indoor and outdoor exhibits near the Birmingham airport. The collection includes unusual prototypes and restored aircraft spanning multiple eras.', 'open', 'https://southernmuseumofflight.org/', null, 'America/Chicago', now()),
  ('Alabama Museum of the Health Sciences', 'alabama-museum-of-the-health-sciences', 'museums', 33.49931, -86.80439, 'Birmingham', 'AL', 'UAB’s medical museum preserves historic surgical tools, diagnostic devices, an iron lung and other objects documenting how medicine changed over time. The collection is displayed in the Pappas Historical Collections Gallery inside Lister Hill Library.', 'open', 'https://www.uab.edu/amhs/visit', null, 'America/Chicago', now()),
  ('Rickwood Field', 'rickwood-field', 'weird-history', 33.50263, -86.85566, 'Birmingham', 'AL', 'Opened in 1910, Rickwood Field is widely recognized as the oldest surviving professional baseball park in the United States. Its preserved grandstand and history involving Negro League and major-league players make it a rare living sports artifact.', 'limited', 'https://www.mlb.com/rickwood', null, 'America/Chicago', now()),
  ('Negro Southern League Museum', 'negro-southern-league-museum', 'weird-history', 33.50838, -86.80953, 'Birmingham', 'AL', 'The museum preserves uniforms, photographs, equipment and stories from Black baseball and the Negro Southern League. Its collection documents players and teams that operated within segregated American baseball.', 'open', 'https://www.birminghamnslm.org/', null, 'America/Chicago', now()),
  ('16th Street Baptist Church', '16th-street-baptist-church', 'weird-history', 33.51658, -86.81479, 'Birmingham', 'AL', 'The church was the target of the 1963 Ku Klux Klan bombing that killed four girls and became a defining event of the Civil Rights Movement. It remains an active congregation as well as a historic site; visits must respect services and church rules.', 'limited', 'https://16thstreetbaptist.org/', null, 'America/Chicago', now()),
  ('Birmingham Civil Rights Institute', 'birmingham-civil-rights-institute', 'weird-history', 33.51594, -86.81499, 'Birmingham', 'AL', 'The institute uses artifacts, recreated environments, photographs and oral histories to examine segregation and Birmingham’s central role in the Civil Rights Movement. It provides context for several nearby sites tied to protests and racial violence.', 'open', 'https://www.bcri.org/', null, 'America/Chicago', now()),
  ('Kelly Ingram Park', 'kelly-ingram-park', 'weird-history', 33.51631, -86.81339, 'Birmingham', 'AL', 'This downtown park was a major gathering and confrontation point during the 1963 Birmingham Campaign. Sculptures and markers now interpret police dogs, fire hoses and youth demonstrators in the exact landscape where the events unfolded.', 'open', 'https://www.birminghamal.gov/parks', null, 'America/Chicago', now()),
  ('Red Mountain Park', 'red-mountain-park', 'weird-history', 33.44518, -86.86233, 'Birmingham', 'AL', 'Trails cross former iron-ore mining land filled with mine entrances, foundations and industrial remnants on Red Mountain. Visitors should stay on marked routes and obey closures around shafts and unstable structures.', 'open', 'https://redmountainpark.org/', null, 'America/Chicago', now()),
  ('African Village in America — Joe Minter', 'african-village-in-america-joe-minter', 'roadside-oddities', 33.47593, -86.84317, 'Birmingham', 'AL', 'Artist Joe Minter transformed his yard into a sprawling environment of welded scrap, signs and sculptures addressing African American history, religion, violence and memory. Because this remains a privately rooted art environment, current visitor access should be checked and all property rules respected.', 'limited', 'https://www.spacesarchives.org/explore/search-the-online-collection/jo-minter-african-village-in-america/', null, 'America/Chicago', now()),
  ('Tannehill Ironworks Historical State Park', 'tannehill-ironworks-historical-state-park', 'weird-history', 33.25781, -87.05946, 'McCalla', 'AL', 'Ruins and reconstructed structures preserve an ironmaking community whose furnaces supplied Confederate industry before Union forces destroyed the works in 1865. The park combines furnace remains, historic buildings, trails and an iron-and-steel museum.', 'open', 'https://www.tannehillstatepark.org/', null, 'America/Chicago', now()),
  ('Brierfield Ironworks Historical State Park', 'brierfield-ironworks-historical-state-park', 'weird-history', 33.03944, -86.94889, 'Brierfield', 'AL', 'This wooded park preserves the remains of a Civil War-era ironworks, including furnace ruins and industrial archaeology. Trails and interpretation allow visitors to explore a landscape where large-scale iron production once dominated the valley.', 'open', 'https://brierfieldironworks.org/', null, 'America/Chicago', now()),
  ('Heart of Dixie Railroad Museum', 'heart-of-dixie-railroad-museum', 'weird-history', 33.09945, -86.75075, 'Calera', 'AL', 'Alabama’s official railroad museum maintains locomotives, passenger cars, cabooses, depots and operating excursion trains. Train rides occur on selected dates, while the grounds and museum collections preserve multiple eras of rail travel.', 'limited', 'https://hodrrm.org/', null, 'America/Chicago', now()),
  ('Tinglewood Carvings at Orr Park', 'tinglewood-carvings-at-orr-park', 'roadside-oddities', 33.09716, -86.85862, 'Montevallo', 'AL', 'Local artist Tim Tingle carved faces, animals and fantasy creatures into dead cedar trees throughout Orr Park, leaving living trees unharmed. The result is a public walking trail filled with dozens of unexpected wooden figures.', 'open', 'https://www.cityofmontevallo.com/OrrPark.aspx', null, 'America/Chicago', now()),
  ('Aldrich Coal Mine Museum', 'aldrich-coal-mine-museum', 'weird-history', 33.10812, -86.8932, 'Montevallo', 'AL', 'The museum occupies former Montevallo Coal Mine Company buildings and preserves mining tools, photographs, a company-store interior and a simulated slope mine. Nearby history includes convict labor and the remains of a once-company-controlled mining community; call ahead for current access.', 'limited', 'https://www.cityofmontevallo.com/AldrichCoalMineMuseum.aspx', null, 'America/Chicago', now()),
  ('World’s Largest Office Chair', 'worlds-largest-office-chair', 'roadside-oddities', 33.65257, -85.82956, 'Anniston', 'AL', 'Built in 1981 to advertise Miller’s Office Furniture, the enormous chair towers above the street at roughly three stories high. It remains an easy exterior photo stop and a classic example of oversized roadside advertising.', 'roadside', 'https://alabama.travel/places-to-go/world-s-largest-office-chair', null, 'America/Chicago', now()),
  ('Berman Museum', 'berman-museum', 'museums', 33.69744, -85.81904, 'Anniston', 'AL', 'The Berman Museum displays weapons, armor, espionage objects, decorative arts and unusual artifacts collected by Farley and Germaine Berman. The eclectic collection includes objects ranging from Asian arms to twentieth-century spy equipment.', 'open', 'https://www.exploreamag.org/berman-museum', null, 'America/Chicago', now()),
  ('Anniston Museum of Natural History', 'anniston-museum-of-natural-history', 'museums', 33.69642, -85.82016, 'Anniston', 'AL', 'Dioramas, fossils, minerals, mounted animals and archaeological objects fill a museum built around wide-ranging natural-history collections. The specimen-heavy galleries retain the feel of an older encyclopedic museum.', 'open', 'https://www.exploreamag.org/anniston-museum', null, 'America/Chicago', now()),
  ('Freedom Riders Greyhound Bus Burning Site', 'freedom-riders-greyhound-bus-burning-site', 'weird-history', 33.63527, -85.90643, 'Anniston', 'AL', 'A national monument site marks the location where a mob attacked and burned a Greyhound bus carrying Freedom Riders on May 14, 1961. Outdoor interpretation preserves the exact roadside landscape connected to the attack.', 'open', 'https://www.nps.gov/frri/index.htm', null, 'America/Chicago', now()),
  ('Freedom Riders National Monument — Greyhound Bus Depot', 'freedom-riders-national-monument-greyhound-bus-depot', 'weird-history', 33.65803, -85.8311, 'Anniston', 'AL', 'The former downtown Greyhound station is part of Freedom Riders National Monument and preserves another key location in the 1961 attacks. Exterior interpretation and scheduled programming connect the depot to the nearby bus-burning site.', 'limited', 'https://www.nps.gov/frri/index.htm', null, 'America/Chicago', now()),
  ('International Motorsports Hall of Fame', 'international-motorsports-hall-of-fame', 'museums', 33.57821, -86.07239, 'Talladega', 'AL', 'Beside Talladega Superspeedway, the museum and Hall of Fame display race cars, motorcycles, trophies and artifacts covering many forms of motorsport. The collection includes machines tied to record runs and major racing figures.', 'open', 'https://www.motorsportshalloffame.com/', null, 'America/Chicago', now()),
  ('Majestic Caverns', 'majestic-caverns', 'roadside-oddities', 33.30678, -86.27771, 'Childersburg', 'AL', 'Formerly known as DeSoto Caverns, this commercial cave features a huge main chamber, formations and a long history of human use. Cave tours are scheduled and ticketed, with current operating days varying through the year.', 'limited', 'https://majesticcaverns.com/', null, 'America/Chicago', now()),
  ('Kymulga Grist Mill & Covered Bridge', 'kymulga-grist-mill-covered-bridge', 'weird-history', 33.33452, -86.29968, 'Childersburg', 'AL', 'A nineteenth-century grist mill and covered bridge survive together beside Talladega Creek. The preserved machinery, timber bridge and riverside setting create a compact industrial-history stop.', 'limited', 'https://alstate.guide/metropolitan/talladega/childersburg/kymulga-grist-mill-covered-bridge', null, 'America/Chicago', now()),
  ('Noccalula Falls — Princess Noccalula Legend', 'noccalula-falls-princess-noccalula-legend', 'folklore', 34.0415, -86.0211, 'Gadsden', 'AL', 'A 90-foot waterfall is paired with the long-told legend of Noccalula, a young Cherokee woman said to have leapt from the cliff rather than accept an unwanted marriage. The story is folklore, while the waterfall and statue provide a concrete public destination.', 'open', 'https://noccalulafallspark.com/', null, 'America/Chicago', now()),
  ('Museum of Wonder Drive-Thru Museum', 'museum-of-wonder-drive-thru-museum', 'roadside-oddities', 32.32926, -85.1682, 'Seale', 'AL', 'Butch Anthony turned stacked shipping containers into a free drive-through gallery filled with folk art, taxidermy, bones, found objects and visual oddities. The drive-through portion is open 24/7; tours of Anthony’s original museum and studio require separate arrangements.', 'open', 'https://museumofwonder.com/visit', null, 'America/Chicago', now()),
  ('Moundville Archaeological Park', 'moundville-archaeological-park', 'weird-history', 33.00272, -87.62814, 'Moundville', 'AL', 'Dozens of Mississippian platform mounds survive at one of the most important Indigenous archaeological sites in the Southeast. A museum and walking paths interpret the city that flourished here centuries before European colonization.', 'open', 'https://moundville.museums.ua.edu/', null, 'America/Chicago', now()),
  ('Alabama Museum of Natural History — Hodges Meteorite', 'alabama-museum-of-natural-history-hodges-meteorite', 'roadside-oddities', 33.21189, -87.54398, 'Tuscaloosa', 'AL', 'The museum’s collections include the famous Sylacauga/Hodges meteorite connected to the 1954 incident in which Ann Hodges was struck by a meteorite fragment inside her home. The object anchors a broader museum of geology, fossils and Alabama natural history.', 'open', 'https://almnh.museums.ua.edu/', null, 'America/Chicago', now()),
  ('Drish House', 'drish-house', 'haunted', 33.19755, -87.56185, 'Tuscaloosa', 'AL', 'This distinctive Greek Revival and Italianate mansion is tied to long-running local stories of phantom lights and unexplained activity, often connected to the deaths of Dr. John Drish and his wife Sarah. It operates as a private event venue, so interior access requires permission or a scheduled event.', 'limited', 'https://historictuscaloosa.org/', null, 'America/Chicago', now()),
  ('Pickens County Courthouse — Face in the Window', 'pickens-county-courthouse-face-in-the-window', 'folklore', 33.26192, -88.09509, 'Carrollton', 'AL', 'A pale face-like image in an upstairs courthouse window is traditionally said to be that of Henry Wells, who was accused of burning an earlier courthouse and lynched in 1878. The supernatural explanation is folklore, but the mark in the glass is a long-standing local curiosity visible from lawful public areas.', 'roadside', 'https://www.tourwestalabama.com/attraction/pickens-county-courthouse/', null, 'America/Chicago', now()),
  ('Old Cahawba Archaeological Park', 'old-cahawba-archaeological-park', 'weird-history', 32.31963, -87.10463, 'Orrville', 'AL', 'Alabama’s first permanent state capital was abandoned after floods, political change and economic decline. Roads, ruins, cemeteries and archaeological remains now form an official historic park where an entire former town can be explored.', 'open', 'https://www.oldcahawba.org/', null, 'America/Chicago', now()),
  ('Wetumpka Impact Crater — Bald Knob Viewpoint', 'wetumpka-impact-crater-bald-knob-viewpoint', 'roadside-oddities', 32.53308, -86.19422, 'Wetumpka', 'AL', 'This marked viewpoint sits on the rim of an approximately 85-million-year-old impact crater created by a meteor or asteroid. The public sign is part of Wetumpka’s self-guided crater route; much surrounding land is private, so stay on public roads and marked viewpoints.', 'roadside', 'https://www.wetumpkaal.gov/365/Wetumpka-Impact-Crater-Commission', null, 'America/Chicago', now()),
  ('Fort Toulouse–Fort Jackson Park', 'fort-toulouse-fort-jackson-park', 'weird-history', 32.50663, -86.25158, 'Wetumpka', 'AL', 'At the meeting of the Coosa and Tallapoosa rivers, the park preserves reconstructed and archaeological remains from a French colonial fort, Fort Jackson and earlier Indigenous occupation. Trails connect forts, a mound and multiple layers of contested history.', 'open', 'https://ahc.alabama.gov/properties/fttoulouse/fttoulouse.aspx', null, 'America/Chicago', now()),
  ('Confederate Memorial Park — Alabama Confederate Soldiers’ Home Site', 'confederate-memorial-park-alabama-confederate-soldiers-home-site', 'weird-history', 32.71812, -86.47442, 'Marbury', 'AL', 'This state historic site preserves the grounds of Alabama’s Confederate Soldiers’ Home, which operated from 1902 to 1939 for aging veterans and some wives and widows. A museum, cemeteries and surviving landscape interpret the institution and the postwar memory culture surrounding it.', 'open', 'https://ahc.alabama.gov/properties/confederate/confederate.aspx', null, 'America/Chicago', now()),
  ('Tuskegee Airmen National Historic Site', 'tuskegee-airmen-national-historic-site', 'weird-history', 32.45539, -85.67983, 'Tuskegee', 'AL', 'Moton Field preserves hangars, exhibits and the training landscape of the Tuskegee Airmen, the pioneering Black military aviators and support personnel of World War II. The National Park Service site occupies the actual airfield where much of the training took place.', 'open', 'https://www.nps.gov/tuai/index.htm', null, 'America/Chicago', now()),
  ('George Washington Carver Museum', 'george-washington-carver-museum', 'weird-history', 32.4297, -85.7066, 'Tuskegee', 'AL', 'Located on the Tuskegee University campus, the National Park Service museum explores George Washington Carver’s scientific work, teaching and art. It preserves laboratory-related materials and exhibits within the institution where he spent much of his career.', 'open', 'https://www.nps.gov/tuin/planyourvisit/gw-carver-museum.htm', null, 'America/Chicago', now()),
  ('Legacy Museum at Tuskegee University', 'legacy-museum-at-tuskegee-university', 'weird-history', 32.4301, -85.7074, 'Tuskegee', 'AL', 'The museum occupies the former Infantile Paralysis Unit of John A. Andrew Memorial Hospital and examines bioethics, science and the U.S. Public Health Service syphilis study in Macon County. Campus visitors must follow Tuskegee University security and pass procedures.', 'limited', 'https://www.tuskegee.edu/libraries/Legacy-Museum.html', null, 'America/Chicago', now()),
  ('Tuskegee History Center', 'tuskegee-history-center', 'weird-history', 32.42296, -85.6915, 'Tuskegee', 'AL', 'The center interprets Macon County’s Native American, European American and African American histories, including civil-rights struggles and the U.S. Public Health Service syphilis study. Exhibits emphasize the people affected by these events rather than treating them as abstract history.', 'limited', 'https://tuskegeecenter.org/', null, 'America/Chicago', now()),
  ('Hank Williams Museum', 'hank-williams-museum', 'weird-history', 32.37948, -86.31068, 'Montgomery', 'AL', 'The museum preserves stage clothing, instruments, records, photographs and personal objects tied to Hank Williams. Its collection includes the Cadillac associated with his final journey, making it a particularly tangible stop for country-music history.', 'open', 'https://thehankwilliamsmuseum.net/', null, 'America/Chicago', now()),
  ('Hank Williams Grave', 'hank-williams-grave', 'weird-history', 32.38543, -86.29106, 'Montgomery', 'AL', 'Hank Williams and his wife Audrey are buried beneath large white marble monuments in Oakwood Cemetery Annex. The graves have become a music-history pilgrimage site; visitors should observe cemetery hours and treat surrounding burials respectfully.', 'limited', 'https://www.montgomeryal.gov/', null, 'America/Chicago', now()),
  ('F. Scott and Zelda Fitzgerald Museum', 'f-scott-and-zelda-fitzgerald-museum', 'weird-history', 32.35873, -86.2923, 'Montgomery', 'AL', 'The Fitzgeralds lived in this Old Cloverdale house in 1931–32, and it is now the world’s only museum dedicated to both F. Scott and Zelda Fitzgerald. Exhibits preserve their books, correspondence, photographs and Montgomery connections.', 'open', 'https://fitzmuse.squarespace.com/', null, 'America/Chicago', now()),
  ('Freedom Rides Museum', 'freedom-rides-museum', 'weird-history', 32.37472, -86.30917, 'Montgomery', 'AL', 'Montgomery’s former Greyhound bus station preserves the site where Freedom Riders arrived in May 1961 and were attacked by a mob. Exhibits inside the restored station document the riders and the interstate travel campaign.', 'open', 'https://ahc.alabama.gov/properties/freedomrides/freedomrides.aspx', null, 'America/Chicago', now()),
  ('The Legacy Museum', 'the-legacy-museum', 'weird-history', 32.38248, -86.30833, 'Montgomery', 'AL', 'Equal Justice Initiative’s museum examines enslavement, racial terror lynching, segregation and mass incarceration through documents, artifacts, art and immersive interpretation. It connects multiple periods of American racial injustice within a single museum experience.', 'open', 'https://museumandmemorial.eji.org/museum', null, 'America/Chicago', now()),
  ('National Memorial for Peace and Justice', 'national-memorial-for-peace-and-justice', 'weird-history', 32.37611, -86.31194, 'Montgomery', 'AL', 'The memorial honors thousands of victims of racial terror lynching with suspended steel monuments representing U.S. counties where documented killings occurred. It is a solemn site designed for remembrance and historical reckoning rather than casual sightseeing.', 'open', 'https://museumandmemorial.eji.org/memorial', null, 'America/Chicago', now()),
  ('Boll Weevil Monument', 'boll-weevil-monument', 'roadside-oddities', 31.31444, -85.85403, 'Enterprise', 'AL', 'Enterprise erected a monument to the boll weevil after the pest devastated cotton farming and pushed local agriculture toward diversification. A classical female figure holds an oversized insect above her head in one of America’s strangest civic monuments.', 'roadside', 'https://www.enterpriseal.gov/', null, 'America/Chicago', now()),
  ('United States Army Aviation Museum', 'united-states-army-aviation-museum', 'weird-history', 31.32419, -85.71311, 'Fort Novosel', 'AL', 'Helicopters, fixed-wing aircraft and experimental machines document U.S. Army aviation from its earliest years through modern rotary-wing operations. The museum is on an active military installation, so visitors must comply with current gate, identification and security requirements.', 'limited', 'https://www.armyaviationmuseum.org/', null, 'America/Chicago', now()),
  ('Africatown Heritage House', 'africatown-heritage-house', 'weird-history', 30.73844, -88.05861, 'Mobile', 'AL', 'The museum centers the story of the Clotilda, the last known slave ship to arrive in the United States, and the community founded by many of its survivors. Artifacts recovered from the wreck and community histories connect Africatown directly to the people who endured the voyage.', 'open', 'https://clotilda.com/', null, 'America/Chicago', now()),
  ('Mobile Medical Museum', 'mobile-medical-museum', 'museums', 30.69301, -88.07754, 'Mobile', 'AL', 'Historic medical instruments, pharmacy objects, anatomical material and archival collections document centuries of medicine on the Gulf Coast. The museum occupies the Vincent-Doan House and presents tools that can look startling by modern standards.', 'limited', 'https://www.mobilemedicalmuseum.org/', null, 'America/Chicago', now()),
  ('Mobile Carnival Museum', 'mobile-carnival-museum', 'folklore', 30.68844, -88.04527, 'Mobile', 'AL', 'Mobile’s museum of Carnival preserves elaborate royal costumes, floats, masks and material from the city’s long Mardi Gras tradition. Exhibits emphasize the secret societies, pageantry and ritual structure behind one of America’s oldest Carnival cultures.', 'open', 'https://www.mobilecarnivalmuseum.com/', null, 'America/Chicago', now()),
  ('Condé-Charlotte Museum', 'cond-charlotte-museum', 'weird-history', 30.68841, -88.04007, 'Mobile', 'AL', 'Built on the site of Mobile’s colonial fort and later used as a jailer’s residence, the house contains rooms interpreted through the city’s French, British, Spanish and American periods. Guided access reveals layers of Gulf Coast colonial history in one structure.', 'limited', 'https://condecharlotte.com/', null, 'America/Chicago', now()),
  ('Church Street Graveyard', 'church-street-graveyard', 'weird-history', 30.68572, -88.05074, 'Mobile', 'AL', 'Established after earlier burial grounds filled, this historic cemetery contains elaborate monuments and graves connected to Mobile’s nineteenth-century residents, epidemics and civic history. Treat it as an active historic cemetery rather than a paranormal playground.', 'open', 'https://www.cityofmobile.org/parks-rec/church-street-graveyard/', null, 'America/Chicago', now()),
  ('USS Alabama Battleship Memorial Park', 'uss-alabama-battleship-memorial-park', 'weird-history', 30.68399, -88.01555, 'Mobile', 'AL', 'Visitors can enter the World War II battleship USS Alabama, submarine USS Drum and extensive aircraft displays at this waterfront park. Tight compartments, gun turrets and preserved machinery turn the warships themselves into the museum.', 'open', 'https://www.ussalabama.com/', null, 'America/Chicago', now()),
  ('Historic Blakeley State Park', 'historic-blakeley-state-park', 'weird-history', 30.74982, -87.91083, 'Spanish Fort', 'AL', 'Wooded roads and earthworks preserve the abandoned town of Blakeley and the battlefield of one of the Civil War’s final major engagements. Foundations, cemetery areas and old streets survive beneath the forest.', 'open', 'https://www.blakeleypark.com/', null, 'America/Chicago', now()),
  ('Fort Mims Historic Site', 'fort-mims-historic-site', 'weird-history', 31.1805, -87.83797, 'Tensaw', 'AL', 'The site preserves the location of the 1813 Fort Mims attack during the Creek War, where hundreds of people were killed or captured. Reconstructed palisade elements, markers and memorials interpret a violent and complex event involving Creek factions, settlers, enslaved people and militia.', 'limited', 'https://fortmims.org/', null, 'America/Chicago', now()),
  ('Tolstoy Park — Henry Stuart House', 'tolstoy-park-henry-stuart-house', 'roadside-oddities', 30.5568, -87.89413, 'Montrose', 'AL', 'Henry Stuart, diagnosed with tuberculosis, built this tiny round domed concrete home by hand in the 1920s as part of a simple-life experiment he called Tolstoy Park. The preserved hut now sits improbably within a modern office complex.', 'open', 'https://npgallery.nps.gov/NRHP/AssetDetail/90ed8e92-f403-4285-8799-4a871a0ab88f/', null, 'America/Chicago', now()),
  ('Fort Gaines', 'fort-gaines', 'weird-history', 30.24881, -88.075, 'Dauphin Island', 'AL', 'Fort Gaines guarded Mobile Bay and played a major role in the 1864 Battle of Mobile Bay. Visitors can explore brick passages, gun positions, tunnels and preserved fort spaces at the eastern tip of Dauphin Island.', 'open', 'https://www.townofdauphinisland.org/fort-gaines', null, 'America/Chicago', now()),
  ('Fort Morgan State Historic Site', 'fort-morgan-state-historic-site', 'weird-history', 30.22806, -88.02306, 'Gulf Shores', 'AL', 'Fort Morgan’s massive masonry walls guarded the entrance to Mobile Bay and figured prominently in the Battle of Mobile Bay. The preserved fort includes tunnels, batteries and later military additions spanning generations of coastal defense.', 'open', 'https://ahc.alabama.gov/properties/fortmorgan/fortmorgan.aspx', null, 'America/Chicago', now()),
  ('Holmes Medical Museum', 'holmes-medical-museum', 'museums', 30.40616, -87.6848, 'Foley', 'AL', 'Foley’s first hospital has been preserved with operating-room equipment, patient rooms, instruments and displays of medical quackery. The old tools and intact hospital spaces make it one of Alabama’s best medical-curiosity museums.', 'limited', 'https://foleyhistoricalarchives.com/holmes-medical-museum/', null, 'America/Chicago', now()),
  ('Bamahenge', 'bamahenge', 'roadside-oddities', 30.33155, -87.5672, 'Elberta', 'AL', 'Artist Mark Cline created a full-size fiberglass Stonehenge replica hidden in the woods near Barber Marina. The stones are arranged to echo the English monument, producing an intentionally surreal roadside destination on the Gulf Coast.', 'open', 'https://barbermarina.com/', null, 'America/Chicago', now()),
  ('World’s Largest Horseshoe Crab — Dinosaur Adventure Land', 'worlds-largest-horseshoe-crab-dinosaur-adventure-land', 'roadside-oddities', 31.35554, -87.17535, 'Repton', 'AL', 'The giant fiberglass-and-foam horseshoe crab nicknamed Crabbie has moved through several states and now resides at Dinosaur Adventure Land in Conecuh County. It measures roughly 67 feet long and remains a bizarre oversized roadside sculpture; check the property’s current visitor rules before arriving.', 'limited', 'https://drdino.com/', null, 'America/Chicago', now()),
  ('Kathryn Tucker Windham Museum', 'kathryn-tucker-windham-museum', 'folklore', 31.88889, -87.74466, 'Thomasville', 'AL', 'This small museum honors Alabama storyteller and journalist Kathryn Tucker Windham, whose books and performances preserved ghost stories and regional folklore across the state. Photographs, writings and personal material connect directly to the woman behind many Alabama supernatural tales.', 'limited', 'https://www.ruralswalabama.org/attraction/kathryn-tucker-windham-museum/', null, 'America/Chicago', now()),
  ('Old Monroe County Courthouse Museum', 'old-monroe-county-courthouse-museum', 'weird-history', 31.5271, -87.3242, 'Monroeville', 'AL', 'The preserved courtroom helped inspire the fictional trial setting in Harper Lee’s To Kill a Mockingbird and was carefully recreated for the film adaptation. Exhibits also cover Lee, Truman Capote and Monroe County history.', 'open', 'https://www.monroecountymuseum.org/old-courthouse-museum', null, 'America/Chicago', now()),
  ('Hank Williams Boyhood Home & Museum', 'hank-williams-boyhood-home-museum', 'weird-history', 31.63946, -86.74195, 'Georgiana', 'AL', 'Hank Williams lived in this house as a child and began developing the musical skills that would define his career. The museum preserves family history, memorabilia and the local story of his early guitar lessons.', 'open', 'https://www.hankmuseum.com/', null, 'America/Chicago', now()),
  ('Gaineswood', 'gaineswood', 'roadside-oddities', 32.50555, -87.83445, 'Demopolis', 'AL', 'Gaineswood grew over decades into an unusually elaborate Greek Revival mansion with domed ceilings, columned rooms and complex decorative details. The site also preserves the history of the enslaved laborers whose work supported the estate.', 'limited', 'https://ahc.alabama.gov/properties/gaineswood/gaineswood.aspx', null, 'America/Chicago', now()),
  ('Bottle Creek Indian Mounds', 'bottle-creek-indian-mounds', 'weird-history', 31.0088, -87.94057, 'Stockton', 'AL', 'On a remote island in the Mobile-Tensaw Delta, this major Mississippian ceremonial center contains numerous platform mounds built between roughly 1250 and 1550. Access is by water and is highly limited; travelers should use authorized tours or current Alabama Historical Commission guidance rather than attempting an unsupervised landing.', 'limited', 'https://ahc.alabama.gov/archaeology.aspx', null, 'America/Chicago', now()),
  ('Pioneer Museum of Alabama', 'pioneer-museum-of-alabama', 'museums', 31.82453, -85.9962, 'Troy', 'AL', 'A collection of relocated historic buildings, farm equipment, a logging locomotive, grist mill and period interiors recreates pieces of rural Alabama life. The grounds function as an open-air museum rather than a single gallery building.', 'open', 'https://www.pioneer-museum.org/', null, 'America/Chicago', now()),
  ('George Washington Carver Interpretive Museum', 'george-washington-carver-interpretive-museum', 'weird-history', 31.22722, -85.39282, 'Dothan', 'AL', 'Located in downtown Dothan, this museum focuses on George Washington Carver and broader African American contributions to science, invention and culture. Exhibits connect Carver’s agricultural work with stories of other innovators.', 'open', 'https://www.gwcarvermuseum.com/', null, 'America/Chicago', now()),
  ('Swift-Coles Historic Home', 'swift-coles-historic-home', 'weird-history', 30.31278, -87.72648, 'Bon Secour', 'AL', 'This Gulf Coast house began as a small dogtrot cabin in 1882 and expanded into a sprawling 6,000-square-foot home filled with period antiques. County preservation staff operate tours on a limited schedule.', 'limited', 'https://www.baldwincountyal.gov/departments/archives-history/bchdc/swift-coles-historic-home', null, 'America/Chicago', now())
on conflict (slug) do update set
  description   = excluded.description,
  public_access = excluded.public_access,
  source        = excluded.source,
  website       = excluded.website,
  verified_at   = excluded.verified_at;

select count(*) as alabama from public.stops where state = 'AL';
